interactiveControl: {
  surface: {
    combined: [
      // emphasis = the pattern; tint = the colour
      { where: { emphasis: "primary" }, partialSurface: { tint: "primary", interior: { background: "tint", foreground: "smart-bw" }, boundary: { border: { color: "transparent" } } } },
